DFLT_TURN, DFLT_SMALL, DFLT_SUBAGENT = 'claude-opus-5-5', 'claude-haiku-5-5', 'claude-sonnet-5-5'
DFLT_MEDIUM = 'gpt-6-luna'
DFLT_LOCAL = 'qwen-4b'   #: the local model to suggest; never a route unless named
DFLT_FALLBACK = 'gemma-e4b'   #: where a job goes once no cloud route can run it
LOCAL_RUNTIMES = ('litert', 'mlx', 'llama', 'ollama')

DEFAULT_POLICY = {'turn': None, 'oneshot': DFLT_MEDIUM, 'inline': None, 'completion': DFLT_SMALL, 'classify': DFLT_SMALL, 'summary': DFLT_MEDIUM, 'subagent': DFLT_SUBAGENT}
_LOCAL_CTX = {'gemma-e2b': 16_384, 'gemma-e4b': 16_384, 'gemma-12b': 16_384, 'qwen-4b': 32_768, 'mini-coder-4b': 32_768, 'ornith-9b': 32_768, 'llama-qwen-0.6b': 32_768, 'llama-qwen-1.7b': 32_768, 'llama-qwen-4b': 32_768}
DFLT_LOCAL_CTX = 32_768


@functools.lru_cache(maxsize=64)
def local_window(runtime, model_id):
    "A local model's trained context window from its own config, else 0."
    try:
        if runtime == 'ollama':
            from rishi.ollama import OllamaClient
            info = OllamaClient().show(model_id).get('model_info') or {}
            return int(next((v for k, v in info.items() if k.endswith('.context_length')), 0) or 0)
        if runtime == 'mlx':
            from rishi.mlx import ctx_len, read_config
            return int(ctx_len(read_config(model_id), 0) or 0)
        if runtime == 'llama':
            from llama_cpp import Llama
            from rishi.llama import get_model
            meta = Llama(get_model(model_id), vocab_only=True, verbose=False).metadata
            return int(meta.get(f"{meta.get('general.architecture')}.context_length") or 0)
    except Exception: pass
    return 0

def local_ctx(name, dflt=DFLT_LOCAL_CTX):
    "The context window to use for local model `name`: `$RAMABANA_LOCAL_CTX` if it sets one, then config.toml's `[model.\"NAME\"]` and `window.local_ctx`, else the table."
    if (ovr := (env('LOCAL_CTX') or '').strip()):
        if ovr.isdigit(): return int(ovr)
        for part in ovr.split(','):
            k, _, v = part.partition(':')
            if k.strip() == name and v.strip().isdigit(): return int(v)
    return model_setting(name).get('max_input_tokens') or setting('window.local_ctx') or _LOCAL_CTX.get(name, dflt)

