def unknown_model(name):
    "The error message for a model name nobody knows, with the closest known names."
    near = difflib.get_close_matches(str(name), list(MODELS), n=2, cutoff=0.6)
    hint = f'; did you mean {" or ".join(repr(n) for n in near)}?' if near else '.'
    return (f'unknown model {name!r}{hint} `/models` lists what is configured, and any vendor/model spec works too.')

PREFIXES = RUNTIME_NAMES
RETIRED = {'claude_code': 'use `claude/` instead: the same models, through Claude Code itself', 'cursor': 'the Cursor backend was removed'}

def _runtime_why(rt):
    "The piece `rt` lacks here: a binary not on PATH, or a package not installed."
    if rt == 'claude': return 'claude_agent_sdk is not installed' if shutil.which('claude') else '`claude` is not on PATH'
    if rt in _RUNTIME_DEPS: return f'{_RUNTIME_DEPS[rt]} is not installed'
    if rt == 'ollama': return 'the ollama daemon does not answer and `ollama` is not on PATH'
    return runtime_detail(rt)

def missing_runtime(spec):
    "Why `spec`'s runtime cannot run on this machine and how to get it; '' when it can. Asked live, never cached."
    rt = getattr(spec, 'runtime', '')
    if rt == 'remote' or rt not in RUNTIME_NAMES or runtime_available(rt): return ''
    if rt == 'copilot': return COPILOT_UNAVAILABLE
    why = _runtime_why(rt)
    return f"{rt} runtime is unavailable{f' ({why})' if why else ''}; {runtime_remedy(rt)}"

def reachable_hint():
    "Which model to try instead, from `available_models`. A suggestion: nothing is switched."
    try: alt = next((r['value'] for r in available_models()), None)
    except Exception: alt = None
    hint = f'{alt} runs here; choose it with `/model {alt}` or the model picker' if alt else 'no model runs on this machine yet'
    return f'{hint}. {SETUP_HINT}'

SETUP_HINT = '`ramabana setup` lists the providers and adds one'

def resolve(name):
    'A `ModelSpec` for `name`: a short name from the tables, or any full `vendor/model` spec; none is `DFLT_TURN`. A runtime this machine lacks is named in `missing`, not raised.'
    sync_models()
    spec = _corrected(_spec_for(name))
    return replace(spec, missing=m) if (m := missing_runtime(spec)) else spec

def _corrected(spec):
    "`spec` with config.toml's `[model.\"NAME\"]` window and output cap over fastllm's; the route name wins over the model id."
    if not (o := model_setting(spec.name, spec.model_id)): return spec
    opts = {**(spec.opts or {}), **({'max_output_tokens': o['max_output_tokens']} if o.get('max_output_tokens') else {})}
    n = o.get('max_input_tokens') or o.get('ctx')
    return replace(spec, ctx=n or spec.ctx, note='' if n else spec.note, opts=opts)

def _window_note(name, mid, note):
    "`note`, or for a window fastllm cannot give, what to set in config.toml."
    if not note.startswith('context window unknown'): return note
    return f'{mid!r} is no model id fastllm knows, so its window is taken as 128k; set max_input_tokens under [model."{name}"] in config.toml'

def _spec_for(name):
    if not name: name = DFLT_TURN
    if name in MODELS:
        backend, mid = MODELS[name]
        config = CUSTOM.get(name, {}).get('config', {})
        if backend not in ('remote', 'copilot'):
            ctx = claude_ctx(mid) if backend == 'claude' else DFLT_AGENT_CTX if backend in AGENTS else local_ctx(name)
            return ModelSpec(name, backend, mid, ctx, opts=config)
        if backend == 'copilot':
            ctx, note = _copilot_ctx(mid)
            return ModelSpec(name, backend, mid, ctx, note, config)
        ctx, note = _cloud_ctx(mid)
        if note and 'bedrock-mantle' in (config.get('base_url') or ''): ctx, note = _cloud_ctx(f'bedrock_mantle/{mid}')   # fastllm tables Bedrock's ids under that vendor
        return ModelSpec(name, backend, mid, ctx, _window_note(name, mid, note) if name in CUSTOM else note, config)
    if name.startswith('azure/') and (dep := name.split('/', 1)[1]):
        ctx, note = _cloud_ctx(dep)
        return ModelSpec(name, 'remote', dep, ctx, _window_note(name, dep, note), {'base_url': azure_endpoint(), 'api_key_env': azure_key_env(), 'api_name': 'openai'})
    if re.match(r'^(?:claude-|(?:opus|sonnet|haiku|fable)-\d)', name):    # an untabled Claude id; Claude Code decides
        mid = name if name.startswith('claude-') else f'claude-{name}'
        return ModelSpec(name, 'claude', mid, claude_ctx(mid))
    if '/' in name:
        runtime, model_id = name.split('/', 1)
        if runtime in RETIRED: raise KeyError(f'{name!r}: the {runtime!r} prefix was removed -- {RETIRED[runtime]}')
        if runtime == 'copilot':
            ctx, note = _copilot_ctx(model_id)
            return ModelSpec(name, 'copilot', model_id, ctx, note)
        if runtime in (*LOCAL_RUNTIMES, *AGENTS):
            ctx = claude_ctx(model_id) if runtime == 'claude' else DFLT_AGENT_CTX if runtime in AGENTS else local_ctx(name)
            return ModelSpec(name, runtime, model_id, ctx)
        from urai import infer_runtime
        if (inferred := infer_runtime(name)) in ('litert', 'mlx', 'llama'):
            return ModelSpec(name, inferred, name, local_ctx(name))
        ctx, note = _cloud_ctx(name)
        return ModelSpec(name, 'remote', name, ctx, note)
    raise KeyError(unknown_model(name))

@functools.lru_cache(maxsize=256)
def _caps(model_id, runtime):
    "`urai.model_caps`, memoised."
    try:
        from urai import model_caps
        return model_caps(model_id, runtime=runtime)
    except Exception: return None

def spec_caps(spec):
    "What `spec`'s model accepts and what it hands back, or `None` where rishi cannot say."
    return _caps(spec.model_id, spec.backend if spec.local else 'remote')

def accepts(spec, kind):
    "Can `spec`'s model be sent `kind`? config.toml's `supports_images` answers for a picture; unknown counts as yes."
    if kind == 'image' and (v := model_setting(spec.name, spec.model_id).get('supports_images')) is not None: return v
    c = spec_caps(spec)
    return True if c is None or not c.known else c.accepts(kind)

def model_note(spec):
    "One line about a resolved model, for a status bar."
    where = 'local' if spec.local else 'Azure OpenAI' if is_azure(spec) else 'cloud'
    out = f'{spec.name} · {where} · {spec.ctx//1000}k ctx'
    if (c := spec_caps(spec)) is not None and (m := c.fmt()): out += f' · {m}'
    return out + (f' · {spec.note}' if spec.note else '') + (f' · {spec.missing}' if getattr(spec, 'missing', '') else '')

