KEY_ENVS = {'openai': 'OPENAI_API_KEY', 'anthropic': 'ANTHROPIC_API_KEY', 'gemini': 'GEMINI_API_KEY', 'openrouter': 'OPENROUTER_API_KEY'}
CODEX_LOGIN = 'Codex login'
DOWN_TTL = 300   #: seconds a cloud model that failed or answered nothing waits before it is tried again

def missing_key(spec):
    "The credential a cloud `spec` needs and this environment lacks: an env var, or `CODEX_LOGIN`; else ''."
    if spec.runtime != 'remote': return ''
    vendor, k = spec.model_id.partition('/')[0], (spec.config or {}).get('api_key_env')
    if is_azure(spec) and not (spec.config or {}).get('base_url'): return 'AZURE_OPENAI_ENDPOINT'
    if vendor == 'codex' and not k: return '' if _codex_login() else CODEX_LOGIN
    k = k or KEY_ENVS.get(vendor)
    return k if k and not os.environ.get(k) else ''

def needs(k):
    "What to tell someone missing credential `k`."
    return f"needs {k}; {'run `codex login`' if k == CODEX_LOGIN else 'set it in the environment'}"

def is_local(name):
    "Whether `name` names an on-device model, from the tables or its prefix, without resolving it."
    return (MODELS.get(name) or (str(name).split('/')[0],))[0] in LOCAL_RUNTIMES

@dataclass
class Routing:
    "Which model runs each job, and where a job goes when its model cannot run here."
    turn: str = None
    policy: dict = field(default_factory=lambda: dict(DEFAULT_POLICY))

    def __post_init__(self):
        sync_models()
        if not self.turn: self.turn = env('MODEL') or setting('jobs.turn') or DFLT_TURN
        self.chosen = set()
        for job in JOBS:   # an env var beats config.toml's `[jobs]`
            if (v := env(f'MODEL_{job.upper()}') or (job != 'turn' and setting(f'jobs.{job}'))): self.policy[job] = v; self.chosen.add(job)
        self._cache, self.notes, self.said, self.news = {}, {}, set(), []
        self.down = {}   # name -> (why, when): a cloud model set aside for `DOWN_TTL`, or until named again

    def own(self, job):
        "Whether `job` has a model of its own: set by env, `set`, or a policy that is not the default."
        return bool(v := self.policy.get(job)) and (job in self.chosen or v != DEFAULT_POLICY.get(job))

    def follows_turn(self, job):
        "Whether `job` stays on a local turn: it has no model of its own, nor through `oneshot`."
        return job != 'turn' and is_local(self.turn) and not self.own(job) and not (job in ONESHOT_JOBS and self.own('oneshot'))

    def name_for(self, job='turn'):
        "The model name for `job`: a local turn's when it follows one, else its policy, then `oneshot` for a cheap job, then `turn`."
        if job == 'turn' or self.follows_turn(job): return self.turn
        if (n := self.policy.get(job)): return n
        if job in ONESHOT_JOBS and (n := self.policy.get('oneshot')): return n
        return self.turn

    def _resolve(self, name):
        "Resolve `name`, cached; one whose runtime was missing is asked again."
        if name not in self._cache or self._cache[name].missing: self._cache[name] = resolve(name)
        return self._cache[name]

    def _usable(self, name):
        "Resolve `name`, refusing a cloud model whose key is not set or that was set aside."
        spec = self._resolve(name)
        if (d := self.down.get(name)) and time.time() - d[1] < DOWN_TTL: raise AgentError(d[0])
        if (k := missing_key(spec)): raise AgentError(needs(k))
        if (m := missing_runtime(spec)): raise AgentError(m)
        return spec

    def alternatives(self, job):
        "Where `job` goes when its own model cannot run here, best first: Sonnet for `DFLT_SMALL`, the other cloud routes, then `DFLT_FALLBACK` on the machine; nowhere for a job on a local turn."
        if self.follows_turn(job): return []
        seen, out, n = {self.name_for(job)}, [], self.name_for(job)
        for alt in (DFLT_SUBAGENT if n == DFLT_SMALL else None, self.policy.get('oneshot') if job in ONESHOT_JOBS else None,
                    self.turn, *(self.policy.get(j) for j in JOBS)):
            if alt and alt not in seen and not is_local(alt):
                seen.add(alt); out.append(alt)
        return out + ([] if DFLT_FALLBACK in seen else [DFLT_FALLBACK])

    def _why(self, name):
        "Why `name` cannot run here, or '' when it can."
        try: self._usable(name); return ''
        except Exception as e: return str(e) if isinstance(e, AgentError) else f'unavailable ({agent_err(e)})'

    def fell(self, n, alt, why):
        "Queue one chat note in `news` each time a model's jobs land somewhere new, however many jobs fell with it."
        if (n, alt) in self.said: return
        self.said.add((n, alt))
        k = missing_key(self._cache[n]) if n in self._cache else ''
        self.news.append(f"{n} unavailable ({f'no {k}' if k else why}); {'small jobs' if n == DFLT_SMALL else 'its jobs'} use {alt}")

    def spec(self, job='turn', fallback=True):
        "The `ModelSpec` for `job`, else another cloud route, else `DFLT_FALLBACK`; failing that, an error naming the job, the model and what it needs."
        n = self.name_for(job)
        try: return self._resolve(n) if job == 'turn' else self._usable(n)   # the turn's key and runtime are `Agent.start`'s to report
        except Exception as e:
            why = str(e) if isinstance(e, AgentError) else f'unavailable ({agent_err(e)})'
            err = AgentError(f'{job} job: {n} {why}')
            if not fallback or job == 'turn': raise err from e
            for alt in self.alternatives(job):
                try: spec = self._usable(alt)
                except Exception: continue
                if spec.local and alt != DFLT_FALLBACK: continue
                self.notes[job] = f'{n} {why}; using {alt}'
                self.fell(n, alt, why)
                return spec
            raise err from e

    def set(self, name, job='turn'):
        "Validate `name`, then point `job` at it."
        spec = resolve(name)
        self.down.pop(name, None)
        if job == 'turn': self.turn = name
        else:
            self.policy[job] = name
            self.chosen.add(job)
        self._cache[name] = spec
        return spec

    def backends(self):
        "The distinct backend/model pairs this policy needs."
        out = set()
        for j in JOBS:
            try: s = self.spec(j)
            except Exception: continue
            out.add((s.backend, s.model_id))
        return out

    def summary(self):
        "The whole policy in one block, with any fallbacks, for a bare `/model`."
        rows = []
        for j in JOBS:
            try: row = model_note(self.spec(j))
            except Exception as e: row = f'unavailable ({agent_err(e)})'
            rows.append(f'{j:11} {row}' + (f'  [{self.notes[j]}]' if j in self.notes else ''))
        return '\n'.join(rows)

